#include <fstream>
int main() {
    std::ifstream in("promote.in");
    std::ofstream out("promote.out");
    std::array<long long, 4> before{}, after{};
    for (int i = 0; i < 4; ++i) in >> before[i] >> after[i];
    std::array<long long, 3> answer{};
    long long crossing = 0;
    for (int i = 3; i >= 1; --i) {
        crossing += after[i] - before[i];
        answer[i - 1] = crossing;
    }
    for (long long value : answer) out << value << '\n';
}
