#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <queue>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("angry.in");
    std::ofstream out("angry.out");
    int n;
    in >> n;
    std::vector<long long> position(n);
    for (long long &value : position) in >> value;
    int best = 0;
    for (int start = 0; start < n; ++start) {
        std::vector<bool> scheduled(n, false);
        std::queue<std::pair<int, int>> events;
        scheduled[start] = true;
        events.push({start, 1});
        int count = 1;
        while (!events.empty()) {
            auto [here, radius] = events.front();
            events.pop();
            for (int next = 0; next < n; ++next) {
                if (!scheduled[next] && std::llabs(position[next] - position[here]) <= radius) {
                    scheduled[next] = true;
                    events.push({next, radius + 1});
                    ++count;
                }
            }
        }
        best = std::max(best, count);
    }
    out << best << '\n';
}
