#include <algorithm>
#include <fstream>
#include <map>
#include <utility>
int main() {
    std::ifstream in("mowing.in");
    std::ofstream out("mowing.out");
    int n;
    in >> n;
    int x = 0, y = 0, clock = 0, answer = 1001;
    std::map<std::pair<int, int>, int> previous;
    previous[{0, 0}] = 0;
    for (int i = 0; i < n; ++i) {
        char direction;
        int steps;
        in >> direction >> steps;
        const int dx = (direction == 'E') - (direction == 'W');
        const int dy = (direction == 'N') - (direction == 'S');
        for (int step = 0; step < steps; ++step) {
            x += dx;
            y += dy;
            ++clock;
            const std::pair<int, int> cell{x, y};
            auto found = previous.find(cell);
            if (found != previous.end()) answer = std::min(answer, clock - found->second);
            previous[cell] = clock;
        }
    }
    out << (answer == 1001 ? -1 : answer) << '\n';
}
